class DistanceLimitedPathsExist:
    def __init__(self, n, edgeList):
        self.parent = list(range(n))
        self.size = [1] * n
        # w[x] = weight of the edge that attached x under its parent
        self.w = [0] * n
        for u, v, d in sorted(edgeList, key=lambda e: e[2]):
            ru, rv = self._root(u), self._root(v)
            if ru == rv:
                continue
            if self.size[ru] < self.size[rv]:
                ru, rv = rv, ru
            # attach the smaller tree rv under ru (no path compression)
            self.parent[rv] = ru
            self.w[rv] = d
            self.size[ru] += self.size[rv]

    def _root(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def _climb(self, x, limit):
        # Go up only through links created by edges with weight < limit
        while self.parent[x] != x and self.w[x] < limit:
            x = self.parent[x]
        return x

    def query(self, p, q, limit):
        return self._climb(p, limit) == self._climb(q, limit)
